import React, { useState, useEffect } from "react"
import axios from "axios"

const SearchBar = () => {
  const [searchTerm, setSearchTerm] = useState("")
  const [member, setMember] = useState([])

  useEffect(() => {
    // function to fetch data based on the search term
    const fetchSearchResults = async () => {
      try {
        const res = await axios.get(`http://localhost:8800/members?search=${searchTerm}`)
        setSearchResults(res.data)
      } catch (error) {
        console.error("Error fetching search results:", error)
      }
    }

    // call the function when searchTerm changes
    fetchSearchResults()
  }, [searchTerm])

  const handleInputChange = (event) => {
    setSearchTerm(event.target.value)
  }

  const search = (searchTerm) => {
    console.log("search ", searchTerm)
  }

  return (
    <div className="searchContainer">
      <div class="searchInner">
        <input className="searchBar" type="text" placeholder="Search members..." value={searchTerm} onChange={handleInputChange}/>
        <button className="button__search" onClick={() => search(searchTerm)}>Search</button>
      </div>
      <div className="dropdown">
        {member.filter(member => {
          const searchTerm = value.toLowerCase()
          const fullname = member.firstname
        })}
        {searchResults.map((result) => (
          <div className="searchItem" key={result.id}>{`${result.firstname} ${result.lastname}`}</div>
        ))}
      </div>
    </div>
  )
}

export default SearchBar
